import fs from 'node:fs';import assert from 'node:assert/strict';import {createHash} from 'node:crypto';
const [file,engine]=process.argv.slice(2);const bytes=fs.readFileSync(file),sha=b=>createHash('sha256').update(b).digest('hex');assert.equal(sha(bytes),'9bc7ee1d06e56e61635ba7cf2e00c27f52bec01eba3b881f141af6d3591aa057');const mod=new WebAssembly.Module(bytes);let inst,body,answer,invokes=0;const enc=new TextEncoder(),dec=new TextDecoder();const get=(p,n)=>new Uint8Array(inst.exports.memory.buffer,p>>>0,n>>>0);const imports={};for(const i of WebAssembly.Module.imports(mod)){imports[i.module]??={};imports[i.module][i.name]=(...a)=>{let name=i.name,field=name.match(/^request-(.*)-(len|read)$/);if(field){let b=field[1]==='method'?enc.encode('POST'):field[1]==='path'?enc.encode('/json'):field[1]==='body'?body:new Uint8Array(8);if(field[2]==='len')return b.length;assert.equal(a[0],0);assert.equal(a[2],b.length);get(a[1],a[2]).set(b);return b.length;}if(name==='response-canonical-write'){answer={status:a[0],body:dec.decode(get(a[1],a[2]))};return 0;}if(name==='wit-table-transact'){invokes++;return [0,0];}if(name.startsWith('error-'))throw Error('unexpected error callback '+name);throw Error(name);};}
inst=new WebAssembly.Instance(mod,imports);let rows=[];for(const [input,status,out,delta] of [['{',422,'{}',0],['{"allow":false,"value":1}',403,'',0],['{"allow":true}',404,'',0],['{"allow":true,"value":{"name":"雪"},"key":"a","second_key":"b","revision":"r","txid":"t","operation_id":"o1","second_operation_id":"o2"}',200,'{"name":"雪"}',1],['{"allow":true,"value":[1,2],"key":"c","second_key":"d","revision":"r2","txid":"t2","operation_id":"o3","second_operation_id":"o4"}',200,'[1,2]',1]]){body=enc.encode(input);answer=null;const prior=invokes;assert.equal(inst.exports.handle(),0);assert.equal(answer.status,status);assert.equal(answer.body,out);assert.equal(invokes-prior,delta);for(const n of ['__wasmc_app_input_pending','__wasmc_host_window_pending','__wasmc_value_pending_allocations'])assert.equal(inst.exports[n](),0);rows.push({input,status,body:out,host_calls:delta});}console.log(JSON.stringify({accepted:true,engine,artifact_sha256:sha(bytes),same_instance:true,host:'in-memory success callback only',rows}));
